const PUBLIC_PAGES = {"/":"<!doctype html><html lang=\"vi\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Cửa hàng sản phẩm số · KEYNEST</title><style>body{margin:0;background:#101114;color:#eeeef0;font:16px/1.8 Arial,sans-serif}main{max-width:900px;margin:auto;padding:32px 24px 64px}a{color:#f3a078}nav{display:flex;flex-wrap:wrap;gap:20px;padding-bottom:24px;border-bottom:1px solid #34363e}h1{font-size:clamp(26px,5vw,36px);line-height:1.3}h2{font-size:20px;line-height:1.5}p{color:#bdc0c8;white-space:pre-line}.legal-section{padding:20px 0;border-top:1px solid #34363e}.legal-section-number{color:#f3a078}.legal-sources{padding:20px 0;border-top:1px solid #34363e;color:#9fa3ae;font-size:12px;line-height:1.8}.legal-sources summary{cursor:pointer}.legal-sources ul{display:grid;gap:10px;padding:14px 0 0;margin:0;list-style:none}.legal-sources a{color:#b8bdc7;text-decoration:underline;text-underline-offset:3px;overflow-wrap:anywhere}</style></head><body><main class=\"container legal-page\"><h1>KEYNEST — Cửa hàng sản phẩm số</h1><p>KEYNEST là cửa hàng game key, gift card, dịch vụ nạp game và công cụ số dành cho khách hàng tại Việt Nam. Bạn có thể xem sản phẩm và chính sách mà không cần đăng nhập. Tài khoản dùng để mua hàng, quản lý số dư mua hàng, nhận sản phẩm và theo dõi hỗ trợ, bảo hành.</p><p>Đăng nhập bằng Google sử dụng email và mã định danh để nhận diện tài khoản KEYNEST, cùng tên và ảnh đại diện để hiển thị hồ sơ của bạn. Bạn cũng có thể đăng nhập bằng email hoặc Discord.</p><nav class=\"legal-tabs\"><a href=\"/\">KEYNEST</a><a href=\"/privacy\">Chính sách bảo mật</a><a href=\"/terms\">Điều khoản dịch vụ</a></nav></main></body></html>","/privacy":"<!doctype html><html lang=\"vi\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Chính sách bảo mật · KEYNEST</title><style>body{margin:0;background:#101114;color:#eeeef0;font:16px/1.8 Arial,sans-serif}main{max-width:900px;margin:auto;padding:32px 24px 64px}a{color:#f3a078}nav{display:flex;flex-wrap:wrap;gap:20px;padding-bottom:24px;border-bottom:1px solid #34363e}h1{font-size:clamp(26px,5vw,36px);line-height:1.3}h2{font-size:20px;line-height:1.5}p{color:#bdc0c8;white-space:pre-line}.legal-section{padding:20px 0;border-top:1px solid #34363e}.legal-section-number{color:#f3a078}.legal-sources{padding:20px 0;border-top:1px solid #34363e;color:#9fa3ae;font-size:12px;line-height:1.8}.legal-sources summary{cursor:pointer}.legal-sources ul{display:grid;gap:10px;padding:14px 0 0;margin:0;list-style:none}.legal-sources a{color:#b8bdc7;text-decoration:underline;text-underline-offset:3px;overflow-wrap:anywhere}</style></head><body><main class=\"container legal-page\"><nav class=\"legal-tabs\"><a href=\"/\">KEYNEST</a><a href=\"/privacy\">Chính sách bảo mật</a><a href=\"/terms\">Điều khoản dịch vụ</a></nav><header class=\"legal-hero\"><h1>Chính sách bảo mật</h1><p>Cập nhật ngày 06/11/2026 · Phiên bản 2026-11-06-v2</p></header><article class=\"legal-document\"><section class=\"legal-section\" id=\"policy-0\"><span class=\"legal-section-number\">1</span><div><h2>Bên xử lý dữ liệu và phạm vi chính sách</h2><p>KEYNEST tổ chức thu thập và sử dụng dữ liệu phục vụ tài khoản, giao dịch và hỗ trợ trên keynest.store, đồng thời là đầu mối tiếp nhận yêu cầu về dữ liệu tại Trung tâm hỗ trợ. Chính sách này giải thích việc xử lý đó; không phải sự cho phép không giới hạn đối với mọi mục đích. Bạn có thể đọc sản phẩm và các chính sách công khai trước khi quyết định đăng ký hoặc mua hàng.</p></div></section><section class=\"legal-section\" id=\"policy-1\"><span class=\"legal-section-number\">2</span><div><h2>Dữ liệu Google và phạm vi truy cập</h2><p>Khi bạn chọn Đăng nhập bằng Google, KEYNEST nhận mã định danh tài khoản, địa chỉ email, trạng thái xác minh email, tên hiển thị và ảnh đại diện trong hồ sơ cơ bản được Google cung cấp. Mã định danh và email dùng để tạo hoặc nhận diện tài khoản KEYNEST; tên và ảnh dùng để hiển thị hồ sơ, lời chào và trao đổi hỗ trợ. KEYNEST không yêu cầu đọc thư Gmail, danh bạ hay tệp Google Drive để đăng nhập. Bạn có thể sử dụng đăng nhập bằng email thay cho Google.</p></div></section><section class=\"legal-section\" id=\"policy-2\"><span class=\"legal-section-number\">3</span><div><h2>Lưu trữ và chia sẻ dữ liệu Google</h2><p>Thông tin hồ sơ Google được xử lý qua Supabase Auth và lưu trong hồ sơ tài khoản KEYNEST để duy trì tài khoản, nhận diện chủ đơn hàng và hỗ trợ khách hàng. Nhân sự quản trị có quyền phù hợp có thể truy cập thông tin cần thiết khi xử lý đơn hàng hoặc yêu cầu hỗ trợ. KEYNEST không bán dữ liệu hồ sơ Google, không sử dụng dữ liệu này để quảng cáo cá nhân hóa hoặc huấn luyện mô hình AI. Dữ liệu có thể được cung cấp cho cơ quan có thẩm quyền khi có yêu cầu hợp pháp. Ảnh Google được tải từ máy chủ của nhà cung cấp khi hiển thị trên website.</p></div></section><section class=\"legal-section\" id=\"policy-3\"><span class=\"legal-section-number\">4</span><div><h2>Ngừng kết nối Google và yêu cầu xóa dữ liệu</h2><p>Bạn có thể thu hồi kết nối KEYNEST trong phần kết nối ứng dụng bên thứ ba của Tài khoản Google. Việc thu hồi quyền không tự xóa tài khoản KEYNEST hoặc chứng từ giao dịch đã có. Để yêu cầu xóa dữ liệu hồ sơ đã nhận từ Google, gửi yêu cầu tại Trung tâm hỗ trợ, nêu rõ tài khoản và phạm vi dữ liệu muốn xóa. Sau khi xác minh chủ tài khoản, KEYNEST sẽ thông báo dữ liệu có thể xóa và dữ liệu cần giữ lại để đối soát, bảo hành hoặc thực hiện nghĩa vụ lưu trữ áp dụng. Không gửi mật khẩu hoặc mã OTP để chứng minh danh tính.</p></div></section><section class=\"legal-section\" id=\"policy-4\"><span class=\"legal-section-number\">5</span><div><h2>Thông tin được xử lý</h2><p>Khi đăng ký bằng email, KEYNEST tiếp nhận tên hiển thị, email và mật khẩu để tạo/xác thực tài khoản; mật khẩu không được công khai và không được lưu dạng rõ trong hồ sơ cửa hàng. Tùy tính năng bạn sử dụng, dữ liệu còn gồm mã tài khoản, ảnh đại diện, mã định danh đăng nhập liên kết, giỏ hàng, sản phẩm/UID hoặc thông tin dịch vụ bạn nhập, đơn hàng, số dư/lịch sử giao dịch, thông tin đối soát ngân hàng, thông tin người bán/rút tiền và nội dung hỗ trợ. Dữ liệu kỹ thuật gồm IP, trình duyệt, phiên đăng nhập và nhật ký bảo mật. Hệ thống lưu phiên bản chính sách, hành động xác nhận và thời điểm chấp thuận. Không yêu cầu mật khẩu email/game, mã OTP, cookie phiên hoặc giấy tờ tùy thân chỉ để đăng ký tài khoản mua hàng; tránh gửi dữ liệu không cần thiết qua ghi chú/hỗ trợ.</p></div></section><section class=\"legal-section\" id=\"policy-5\"><span class=\"legal-section-number\">6</span><div><h2>Mục đích sử dụng</h2><p>Dữ liệu đăng ký dùng để tạo, đăng nhập, khôi phục và bảo vệ tài khoản, nhận diện chủ đơn và liên hệ về dịch vụ tài khoản. Dữ liệu đặt hàng/thanh toán dùng để thực hiện yêu cầu mua, giao sản phẩm, đối soát, quản lý số dư, bảo hành và giải quyết tranh chấp; dữ liệu hỗ trợ dùng để xử lý chính yêu cầu bạn gửi. Nhật ký kỹ thuật phục vụ an toàn hệ thống, chống gian lận và giới hạn truy cập. Chỉ xử lý dữ liệu phù hợp với mục đích đã thông báo hoặc căn cứ hợp pháp khác áp dụng; không coi sự im lặng là đồng ý. KEYNEST không lấy việc đăng ký hoặc mua hàng làm sự đồng ý nhận quảng cáo, bán dữ liệu hay sử dụng dữ liệu vào mục đích không liên quan.</p></div></section><section class=\"legal-section\" id=\"policy-6\"><span class=\"legal-section-number\">7</span><div><h2>Sự đồng ý, lựa chọn và rút lại sự đồng ý</h2><p>Biểu mẫu đăng ký yêu cầu bạn chủ động xác nhận điều khoản và đồng ý xử lý dữ liệu cần thiết để cung cấp tài khoản; các ô mặc định chưa tích. Các ô xác nhận chỉ xuất hiện tại biểu mẫu đăng ký. Đăng nhập bằng email/mật khẩu hoặc Google/Discord không yêu cầu tích lại các ô này. Google/Discord xác thực tại nhà cung cấp và có thể tạo hồ sơ KEYNEST khi bạn chưa có tài khoản; hệ thống không ghi nhận bạn đã tích xác nhận nếu không có hành động đó. Nếu không đồng ý phần xử lý cần thiết, bạn có thể không tạo tài khoản và vẫn đọc nội dung công khai. Không có sự đồng ý quảng cáo bắt buộc kèm theo. Bạn có thể gửi yêu cầu rút lại sự đồng ý hoặc hạn chế xử lý tại Trung tâm hỗ trợ; nêu tài khoản, mục đích và phạm vi muốn dừng. Sau khi xác minh bằng thông tin phù hợp, KEYNEST trao đổi tác động đến tài khoản/đơn hàng và xử lý yêu cầu theo quy định. Rút lại sự đồng ý không tự xóa nghĩa vụ giao dịch đã phát sinh hoặc dữ liệu bắt buộc phải lưu theo căn cứ pháp luật khác; KEYNEST phải giải thích phần tiếp tục lưu và lý do, không suy diễn sự đồng ý mới từ việc tiếp tục truy cập.</p></div></section><section class=\"legal-section\" id=\"policy-7\"><span class=\"legal-section-number\">8</span><div><h2>Google, Discord và ảnh đại diện</h2><p>Nếu bạn chọn đăng nhập bằng Google hoặc Discord, website nhận thông tin hồ sơ do nhà cung cấp trả về qua Supabase Auth. Ảnh đại diện có thể được lấy từ nhà cung cấp. Ảnh tự tải lên được lưu dưới dạng tệp và hồ sơ lưu đường dẫn; người biết đường dẫn ảnh có thể xem ảnh đó.</p></div></section><section class=\"legal-section\" id=\"policy-8\"><span class=\"legal-section-number\">9</span><div><h2>Cookie và bộ nhớ trình duyệt</h2><p>Website sử dụng cookie xác thực có thuộc tính HttpOnly để duy trì và làm mới phiên đăng nhập. Token truy cập có thể được giữ trong bộ nhớ ứng dụng để xác thực yêu cầu đến máy chủ. Trình duyệt còn lưu giỏ hàng và trạng thái giao diện trong bộ nhớ cục bộ hoặc bộ nhớ phiên. Bạn có thể xóa dữ liệu website trong trình duyệt; thao tác này có thể làm mất giỏ hàng cục bộ và yêu cầu đăng nhập lại.</p></div></section><section class=\"legal-section\" id=\"policy-9\"><span class=\"legal-section-number\">10</span><div><h2>Dịch vụ tham gia xử lý</h2><p>Supabase cung cấp xác thực, cơ sở dữ liệu và lưu trữ tệp; Google/Discord tham gia khi bạn chọn đăng nhập liên kết; Tingee, Pay2S, SePay và ngân hàng tham gia theo phương thức thanh toán được bật. Cloudflare bảo vệ và phân phối truy cập; Google reCAPTCHA xác minh chống spam khi được bật; Brevo gửi email giao dịch khi dịch vụ email được cấu hình. Người bán chỉ nhận thông tin cần cho đơn của họ và trao đổi hỗ trợ; quản trị viên có quyền phù hợp xử lý vận hành/khiếu nại. Khi tải ảnh từ Steam hoặc nhà cung cấp avatar, dịch vụ đó nhận thông tin kết nối như IP. KEYNEST không bán dữ liệu; chỉ chia sẻ theo mục đích đã thông báo, yêu cầu của bạn hoặc yêu cầu hợp pháp của cơ quan có thẩm quyền, không công khai mật khẩu hay dữ liệu giao hàng cho người không có quyền.</p></div></section><section class=\"legal-section\" id=\"policy-10\"><span class=\"legal-section-number\">11</span><div><h2>Nơi xử lý, thời gian lưu và kết thúc xử lý</h2><p>Dữ liệu được xử lý tại máy chủ website và dịch vụ nêu trên; tùy hạ tầng của nhà cung cấp, có thể được xử lý/lưu ngoài Việt Nam. Việc chọn đăng nhập liên kết hoặc thanh toán không phải sự cho phép vô hạn cho mọi bên nhận; hoạt động chuyển dữ liệu phải tuân thủ quy định áp dụng. Dữ liệu hồ sơ được giữ để duy trì tài khoản; dữ liệu đơn, thanh toán, bảo hành và chấp thuận được giữ trong thời gian còn cần cho thực hiện giao dịch, xử lý yêu cầu/tranh chấp và nghĩa vụ lưu trữ pháp luật. Không cam kết xóa ngay chứng từ đang cần đối soát hay đang chịu nghĩa vụ giữ lại. Khi yêu cầu chấm dứt/xóa được tiếp nhận, KEYNEST xem xét từng nhóm dữ liệu, thông báo phạm vi, căn cứ và thời gian xử lý áp dụng; xóa hoặc ẩn danh dữ liệu không còn cần thiết theo quy trình xử lý yêu cầu. Bản sao lưu và nhật ký tại nhà cung cấp tuân theo thời hạn của dịch vụ và nghĩa vụ áp dụng, không được hiểu là quyền sử dụng dữ liệu vĩnh viễn.</p></div></section><section class=\"legal-section\" id=\"policy-11\"><span class=\"legal-section-number\">12</span><div><h2>Bảo vệ và quản lý dữ liệu</h2><p>Bạn có thể cập nhật tên, ảnh đại diện, bật xác thực hai bước và thu hồi các phiên khác trong tài khoản. Dữ liệu được lưu phục vụ hoạt động tài khoản, thực hiện đơn hàng, đối soát, bảo hành, giải quyết khiếu nại và nghĩa vụ lưu trữ áp dụng. Việc xóa tài khoản không đồng nghĩa mọi chứng từ giao dịch có thể được xóa ngay. Khi nhận yêu cầu xóa, KEYNEST sẽ kiểm tra dữ liệu liên quan và thông báo phạm vi có thể xử lý, cùng lý do nếu cần tiếp tục lưu giữ.</p></div></section><section class=\"legal-section\" id=\"policy-12\"><span class=\"legal-section-number\">13</span><div><h2>Liên hệ về quyền riêng tư</h2><p>Bạn có quyền được biết, đồng ý/không đồng ý và rút lại sự đồng ý; xem, yêu cầu cung cấp, chỉnh sửa, xóa, hạn chế hoặc phản đối xử lý; khiếu nại, tố cáo, khởi kiện và yêu cầu bồi thường theo điều kiện pháp luật. Tại Trung tâm hỗ trợ, chọn tạo yêu cầu, nêu tài khoản và quyền/phạm vi dữ liệu cần xử lý; có thể dùng kênh liên hệ ở chân trang khi không đăng nhập được. KEYNEST xác minh chủ tài khoản bằng biện pháp phù hợp, tiếp nhận và phản hồi theo thời hạn luật định đối với từng yêu cầu; nếu cần từ chối hoặc tiếp tục giữ một phần dữ liệu phải nêu lý do/căn cứ áp dụng. Có thể tự sửa tên/ảnh, quản lý phiên và bật MFA trong Tài khoản. Không gửi mật khẩu hay OTP. Yêu cầu về quyền riêng tư không buộc bạn từ bỏ quyền khiếu nại với cơ quan có thẩm quyền.</p></div></section><section class=\"legal-section\" id=\"policy-13\"><span class=\"legal-section-number\">14</span><div><h2>Trẻ em và người cần người đại diện</h2><p>Khi pháp luật yêu cầu sự đồng ý hoặc đại diện của cha mẹ/người giám hộ đối với việc xử lý dữ liệu hoặc giao dịch, cần thực hiện việc đó trước khi cung cấp dữ liệu và sử dụng chức năng tương ứng. Người đại diện có thể liên hệ KEYNEST để yêu cầu kiểm tra, hạn chế hoặc xóa dữ liệu theo quy định. Không dùng tài khoản của người khác hoặc cung cấp dữ liệu của trẻ em/người khác khi chưa có quyền hợp pháp.</p></div></section><section class=\"legal-section\" id=\"policy-14\"><span class=\"legal-section-number\">15</span><div><h2>Cập nhật chính sách</h2><p>Chính sách tham chiếu Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15 và pháp luật liên quan. Ngày cập nhật và phiên bản được công bố tại trang này; bạn có thể in/lưu nội dung. Thay đổi mục đích cần sự đồng ý mới phải được thông báo và lấy lại xác nhận phù hợp; không xem việc sửa trang chính sách là bạn tự động đồng ý mọi mục đích mới. Bạn có thể hỏi về nội dung hoặc yêu cầu xem bản chính sách gắn với lần xác nhận qua Trung tâm hỗ trợ.</p></div></section><details class=\"legal-sources\"><summary>Tham khảo căn cứ pháp lý</summary><ul><li><a href=\"https://chinhphu.vn/?docid=214590&amp;pageid=27160&amp;typegroupid=3\" target=\"_blank\" rel=\"noopener noreferrer\">Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15</a></li><li><a href=\"https://chinhphu.vn/?classid=1&amp;docid=208363&amp;orggroupid=1&amp;pageid=27160\" target=\"_blank\" rel=\"noopener noreferrer\">Luật Bảo vệ quyền lợi người tiêu dùng 19/2023/QH15</a></li><li><a href=\"https://vanban.chinhphu.vn/?classid=1&amp;docid=216503&amp;pageid=27160&amp;typegroupid=3\" target=\"_blank\" rel=\"noopener noreferrer\">Luật Thương mại điện tử 122/2025/QH15</a></li></ul></details></article><a href=\"/support\">Trung tâm hỗ trợ KEYNEST</a></main></body></html>","/terms":"<!doctype html><html lang=\"vi\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Điều khoản dịch vụ · KEYNEST</title><style>body{margin:0;background:#101114;color:#eeeef0;font:16px/1.8 Arial,sans-serif}main{max-width:900px;margin:auto;padding:32px 24px 64px}a{color:#f3a078}nav{display:flex;flex-wrap:wrap;gap:20px;padding-bottom:24px;border-bottom:1px solid #34363e}h1{font-size:clamp(26px,5vw,36px);line-height:1.3}h2{font-size:20px;line-height:1.5}p{color:#bdc0c8;white-space:pre-line}.legal-section{padding:20px 0;border-top:1px solid #34363e}.legal-section-number{color:#f3a078}.legal-sources{padding:20px 0;border-top:1px solid #34363e;color:#9fa3ae;font-size:12px;line-height:1.8}.legal-sources summary{cursor:pointer}.legal-sources ul{display:grid;gap:10px;padding:14px 0 0;margin:0;list-style:none}.legal-sources a{color:#b8bdc7;text-decoration:underline;text-underline-offset:3px;overflow-wrap:anywhere}</style></head><body><main class=\"container legal-page\"><nav class=\"legal-tabs\"><a href=\"/\">KEYNEST</a><a href=\"/privacy\">Chính sách bảo mật</a><a href=\"/terms\">Điều khoản dịch vụ</a></nav><header class=\"legal-hero\"><h1>Điều khoản dịch vụ</h1><p>Cập nhật ngày 06/11/2026 · Phiên bản 2026-11-06-v2</p></header><article class=\"legal-document\"><section class=\"legal-section\" id=\"policy-0\"><span class=\"legal-section-number\">1</span><div><h2>Phạm vi áp dụng và đầu mối KEYNEST</h2><p>Các điều khoản này áp dụng cho tài khoản và giao dịch sản phẩm số tại keynest.store. KEYNEST là đầu mối vận hành website và tiếp nhận yêu cầu tại Trung tâm hỗ trợ trên website; các kênh liên hệ bổ sung được công bố ở chân trang. Với sản phẩm do người bán khác cung cấp, thông tin người bán được hiển thị tại sản phẩm và được lưu cùng đơn hàng; KEYNEST tiếp nhận khiếu nại và phối hợp xử lý, không dùng việc có người bán khác để loại trừ trách nhiệm của mình theo pháp luật.</p></div></section><section class=\"legal-section\" id=\"policy-1\"><span class=\"legal-section-number\">2</span><div><h2>Tài khoản và sử dụng dịch vụ</h2><p>KEYNEST cung cấp game key, gift card, gói nạp game và công cụ số. Bạn cần cung cấp thông tin chính xác, bảo vệ thông tin đăng nhập và chỉ sử dụng dịch vụ cho mục đích hợp pháp. Không sử dụng sản phẩm để xâm nhập trái phép, lừa đảo, phát tán mã độc hoặc gây hại cho hệ thống khác.</p></div></section><section class=\"legal-section\" id=\"policy-2\"><span class=\"legal-section-number\">3</span><div><h2>Thông tin sản phẩm</h2><p>Kiểm tra nền tảng, khu vực kích hoạt, mệnh giá, thời hạn và hướng dẫn của từng gói trước khi mua. Với sản phẩm nạp game, bạn chịu trách nhiệm kiểm tra mã người chơi và máy chủ đã nhập. Điều kiện sử dụng của nhà phát hành vẫn áp dụng.</p></div></section><section class=\"legal-section\" id=\"policy-3\"><span class=\"legal-section-number\">4</span><div><h2>Đặt hàng và thanh toán</h2><p>Trước khi đặt hàng, bạn có thể xem và sửa gói bán, số lượng, thông tin dịch vụ, mã giảm giá, phương thức thanh toán và tổng tiền trong giỏ hàng; mở lại trang sản phẩm để kiểm tra khu vực, thời hạn, ngày giao dự kiến và bảo hành. Giá hiển thị bằng đồng Việt Nam; phí thanh toán được hiển thị riêng, hiện là miễn phí. Nếu phát sinh khoản phí hoặc thay đổi giá làm tăng số tiền phải trả, cần được thông báo và xác nhận trước khi thu thêm. Bạn chủ động tích ô đồng ý điều kiện giao dịch rồi chọn Đặt hàng &amp; thanh toán để gửi yêu cầu có nghĩa vụ thanh toán. Website xác nhận đã tạo đơn bằng mã đơn và trạng thái trong Đơn hàng. Đơn chuyển khoản chỉ được xử lý sau khi khoản tiền phù hợp được xác nhận; mã QR không phải bằng chứng đã trả tiền. Khi chuyển khoản, giữ đúng số tiền và nội dung; giao dịch không khớp cần đối soát qua hỗ trợ.</p></div></section><section class=\"legal-section\" id=\"policy-4\"><span class=\"legal-section-number\">5</span><div><h2>Giao sản phẩm</h2><p>Sản phẩm được giao trực tuyến và có thể theo dõi trong mục Đơn hàng. Với sản phẩm dạng mã hoặc tài khoản, thông tin nhận hàng xuất hiện trong chi tiết đơn khi được giao. Dịch vụ nạp game được thực hiện theo thông tin người chơi đã cung cấp, không giao key. Thời gian xử lý phụ thuộc từng gói và trạng thái thanh toán; không phải mọi đơn đều được giao ngay. Nếu đơn chưa giao hoặc có sai lệch, gửi yêu cầu gắn với đơn hàng để được kiểm tra. Không công khai mã hoặc thông tin tài khoản được giao.</p></div></section><section class=\"legal-section\" id=\"policy-5\"><span class=\"legal-section-number\">6</span><div><h2>Bảo hành và hoàn tiền</h2><p>Thời hạn bảo hành theo từng gói được lưu trong đơn. Khi có lỗi hoặc giao sai, gửi yêu cầu từ chi tiết đơn kèm bằng chứng đã che thông tin nhạy cảm. KEYNEST kiểm tra và trao đổi phương án sửa, thay thế, hủy hoặc hoàn tiền tùy tình huống và quyền theo pháp luật; gửi yêu cầu không đồng nghĩa đã được duyệt. Website hiện hỗ trợ ghi khoản hoàn vào số dư mua hàng. Cách xử lý này không tước quyền yêu cầu phương thức hoàn trả được pháp luật quy định; khi pháp luật yêu cầu hoàn theo phương thức đã thanh toán, phương thức khác chỉ áp dụng khi khách hàng đồng ý. Có thể trao đổi phương thức hoàn qua hỗ trợ trước khi xử lý. Việc mã đã được giao/sử dụng cần kiểm tra thực tế, không phải lý do tự động từ chối mọi khiếu nại hoặc trách nhiệm đối với sản phẩm lỗi.</p></div></section><section class=\"legal-section\" id=\"policy-6\"><span class=\"legal-section-number\">7</span><div><h2>Ví và mã giảm giá</h2><p>Số dư ví KEYNEST là số dư tài khoản mua hàng trên website, không phải tài khoản ngân hàng. Kiểm tra số tiền trước khi nạp và theo dõi kết quả trong lịch sử giao dịch. Các giới hạn về thời gian, sản phẩm, giá trị đơn và số lượt dùng của mã giảm giá được kiểm tra khi áp dụng. Nếu số dư hoặc lịch sử giao dịch có sai lệch, liên hệ hỗ trợ kèm mã giao dịch; không chuyển thêm tiền để thử lại khi giao dịch cũ đang được đối soát.</p></div></section><section class=\"legal-section\" id=\"policy-7\"><span class=\"legal-section-number\">8</span><div><h2>Hỗ trợ và giải quyết khiếu nại</h2><p>Gửi yêu cầu tại Trung tâm hỗ trợ kèm mã đơn/giao dịch, mô tả và kết quả mong muốn. Yêu cầu và phản hồi được lưu trong tài khoản. KEYNEST tiếp nhận, xác minh, phối hợp người bán hoặc bên thanh toán khi cần và thông báo phương án xử lý; nếu cần thêm thông tin sẽ trao đổi qua yêu cầu. Bạn có thể yêu cầu thương lượng theo quy định của Luật Bảo vệ quyền lợi người tiêu dùng; nếu không đạt thỏa thuận, có thể nhờ cơ quan bảo vệ người tiêu dùng, hòa giải, trọng tài khi có thỏa thuận hợp lệ hoặc tòa án có thẩm quyền. Không có điều khoản nào buộc bạn từ bỏ quyền khiếu nại, khởi kiện hoặc bồi thường theo pháp luật.</p></div></section><section class=\"legal-section\" id=\"policy-8\"><span class=\"legal-section-number\">9</span><div><h2>Hủy đơn, đặt trước và quyền trong giao dịch từ xa</h2><p>Đơn chuyển khoản còn chờ thanh toán có chức năng hủy trong Đơn hàng; đơn quá hạn được chuyển trạng thái hết hạn. Nếu đã chuyển tiền nhưng đơn hủy/hết hạn, liên hệ hỗ trợ kèm chứng từ để đối soát, không chuyển thêm tiền để thử lại. Với đặt trước, ngày giao dự kiến và điều kiện từng gói được hiển thị trước khi đặt; khi chậm giao hoặc không thể thực hiện, bạn có thể yêu cầu hỗ trợ để thỏa thuận hoặc thực hiện quyền chấm dứt/hoàn trả theo pháp luật. Trường hợp bên kinh doanh cung cấp thiếu hoặc sai thông tin bắt buộc trong giao dịch từ xa, quyền tại Điều 38 Luật Bảo vệ quyền lợi người tiêu dùng vẫn được bảo lưu, bao gồm quyền đơn phương chấm dứt trong thời hạn luật định khi đủ điều kiện. Không áp dụng quy tắc “mua hàng số thì không được hoàn trong mọi trường hợp”.</p></div></section><section class=\"legal-section\" id=\"policy-9\"><span class=\"legal-section-number\">10</span><div><h2>Xác nhận điện tử và bản lưu giao dịch</h2><p>Ô xác nhận không được tích sẵn. Bản ghi chấp thuận gắn với phiên bản điều khoản/chính sách và thời điểm máy chủ ghi nhận. Khi đặt hàng, xác nhận được lưu cùng dữ liệu đơn để đối chiếu; việc thử gửi lại cùng yêu cầu không tạo nghĩa vụ thanh toán lần hai. Bạn có thể xem chi tiết đơn, lịch sử thanh toán và yêu cầu hỗ trợ trong tài khoản, lưu/in các trang chính sách và tải bản thông tin giao dịch có xác nhận từ chi tiết đơn. Nếu cần giải thích điều kiện, hãy hỏi hỗ trợ trước khi đặt. Điều kiện riêng không được làm giảm quyền bắt buộc của người tiêu dùng.</p></div></section><section class=\"legal-section\" id=\"policy-10\"><span class=\"legal-section-number\">11</span><div><h2>Dữ liệu tài khoản và pháp luật áp dụng</h2><p>Việc xử lý dữ liệu được giải thích tại Chính sách bảo mật, gồm loại dữ liệu, mục đích, bên nhận, lưu trữ và cách thực hiện quyền. Xác nhận điều khoản không đồng nghĩa đồng ý quảng cáo hoặc bán dữ liệu. Các giao dịch được xem xét theo pháp luật Việt Nam, trong đó có Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15, Luật Bảo vệ quyền lợi người tiêu dùng 19/2023/QH15 và Luật Thương mại điện tử 122/2025/QH15. Khi nội dung công bố mâu thuẫn với quy định bắt buộc, quy định pháp luật tương ứng được ưu tiên.</p></div></section><section class=\"legal-section\" id=\"policy-11\"><span class=\"legal-section-number\">12</span><div><h2>Cập nhật điều khoản</h2><p>Điều khoản và điều kiện của từng gói được công bố để bạn xem trước khi xác nhận mua hàng. Các thay đổi được cập nhật tại trang này cùng ngày cập nhật; thay đổi không tự động làm mất quyền lợi đã được xác nhận cho đơn hàng trước đó. Nếu có nội dung chưa rõ, hãy liên hệ hỗ trợ trước khi thanh toán.</p></div></section><details class=\"legal-sources\"><summary>Tham khảo căn cứ pháp lý</summary><ul><li><a href=\"https://chinhphu.vn/?docid=214590&amp;pageid=27160&amp;typegroupid=3\" target=\"_blank\" rel=\"noopener noreferrer\">Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15</a></li><li><a href=\"https://chinhphu.vn/?classid=1&amp;docid=208363&amp;orggroupid=1&amp;pageid=27160\" target=\"_blank\" rel=\"noopener noreferrer\">Luật Bảo vệ quyền lợi người tiêu dùng 19/2023/QH15</a></li><li><a href=\"https://vanban.chinhphu.vn/?classid=1&amp;docid=216503&amp;pageid=27160&amp;typegroupid=3\" target=\"_blank\" rel=\"noopener noreferrer\">Luật Thương mại điện tử 122/2025/QH15</a></li></ul></details></article><a href=\"/support\">Trung tâm hỗ trợ KEYNEST</a></main></body></html>"};
// PAGE is embedded by scripts/build-country-worker.js; no origin fetch needed for blocked visitors.
export default {
  async fetch(request) {
    const url = new URL(request.url);
    const read = request.method === 'GET' || request.method === 'HEAD';
    // These POST endpoints still authenticate provider signatures/tokens in Node.
    const webhook = request.method === 'POST' && ['/api/webhooks/pay2s', '/api/webhooks/sepay'].includes(url.pathname);
    if (webhook || request.cf?.country === 'VN') return fetch(request);
    // Public browsing is global; account and transaction routes remain restricted.
    // Do not grant access based on a spoofable Googlebot User-Agent.
    const publicPage = ['/', '/catalog', '/guide', '/sitemap.xml', '/robots.txt'].includes(url.pathname.replace(/\/$/, '') || '/')
      || /^\/products\/[a-z0-9-]{1,120}\/?$/.test(url.pathname);
    const publicData = ['/api/config', '/api/products', '/api/catalog', '/api/categories', '/api/banners', '/api/promotions', '/api/announcements'].includes(url.pathname)
      || /^\/api\/products\/[a-zA-Z0-9-]+(?:\/(?:reviews|comments))?$/.test(url.pathname);
    const publicAsset = /^\/assets\/[a-zA-Z0-9_.-]+$/.test(url.pathname);
    if (read && (publicPage || publicData || publicAsset)) {
      const headers = new Headers(request.headers);
      headers.delete('Cookie');
      headers.delete('Authorization');
      return fetch(new Request(request, { headers }));
    }
    const publicImage = /^\/images\/(share|products)\/[a-zA-Z0-9_-]+\.(png|jpg|jpeg|webp|svg)$/.test(url.pathname)
      || /^\/api\/media\/[a-zA-Z0-9_-]+\.webp$/.test(url.pathname);
    if (read && publicImage) {
      url.search = '';
      return fetch(new Request(url, { method: request.method }));
    }
    // Keep legal information available abroad, but show the region screen at the homepage.
    const page = url.pathname.replace(/\/$/, '') || '/';
    if (read && page !== '/' && Object.hasOwn(PUBLIC_PAGES, page)) {
      return new Response(request.method === 'HEAD' ? null : PUBLIC_PAGES[page], {
        headers: {
          'Content-Type': 'text/html; charset=utf-8',
          'Cache-Control': 'private, no-store',
          'X-Keynest-Region-Worker': 'vietnam-region-v5',
          'X-Content-Type-Options': 'nosniff',
          'Content-Security-Policy': "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'",
        },
      });
    }
    const headers = {
      'X-Keynest-Region-Worker': 'vietnam-region-v5',
      'Cache-Control': 'private, no-store',
      'X-Content-Type-Options': 'nosniff',
      'X-Robots-Tag': 'noindex, nofollow',
      'Content-Security-Policy': "default-src 'none'; style-src 'unsafe-inline'; font-src data:; base-uri 'none'; frame-ancestors 'none'; form-action 'none'",
    };
    const api = url.pathname === '/api' || url.pathname.startsWith('/api/');
    headers['Content-Type'] = api ? 'application/json; charset=utf-8' : 'text/html; charset=utf-8';
    const body = api ? JSON.stringify({ code: 'REGION_RESTRICTED', error: 'KEYNEST hiện chỉ hoạt động tại Việt Nam.' }) : PAGE;
    return new Response(request.method === 'HEAD' ? null : body, { status: 403, headers });
  },
};
